#!/bin/sh
# Print the three most frequent client IPs, resolving equal counts by the
# position at which an IP first occurs in the log.
awk '
{
    ip = $1
    if (!(ip in count))
        first[ip] = ++seen
    count[ip]++
}
END {
    for (rank = 1; rank <= 3; rank++) {
        chosen = ""
        best_count = -1
        best_first = 0

        for (ip in count) {
            if (!(ip in emitted) &&
                (count[ip] > best_count ||
                 (count[ip] == best_count &&
                  (chosen == "" || first[ip] < best_first)))) {
                chosen = ip
                best_count = count[ip]
                best_first = first[ip]
            }
        }

        if (chosen == "")
            break
        print chosen
        emitted[chosen] = 1
    }
}
' access.log

